arguments.command:
cd /tmp/vally-eval-trial-p56TJv && P=.copilot-tracking/skraft-plans/pricing && D=$P/details/2026-08-12 && E=$P/evidence/2026-08-12/discount && mkdir -p $P/features tests/CheckoutPricing.UnitTest/Features/Discount $E
cat > $P/features/pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: Bronze, Silver, Gold (AC-1..AC-4) are decided and executable.
  # NOT DECIDED: Platinum. The business has not agreed a reduction, so no
  # scenario exists for it and no expected value may be invented.
  # Platinum scenarios are added only once the business supplies the value (escalated to DISCUSS).

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer's reduction lands on a whole cent in the customer's favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/Discount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class LoyaltyDiscountAcceptanceTests
{
    [Theory]
    // Bronze customer is charged the Bronze price (AC-1)
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Returning_customer_is_charged_the_price_of_their_loyalty_tier(
        LoyaltyTier tier, int subtotalCents, int expectedChargedCents)
    {
        var quote = new CalculateLoyaltyDiscount().Handle(
            new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > $E/acceptance-red.stdout 2>&1; echo $? > $E/acceptance-red.exit; git rev-parse HEAD > $E/acceptance-red.rev; cat $E/acceptance-red.exit; grep -E "Assert|Expected|Actual|error|Failed" $E/acceptance-red.stdout | head

